// ─── File: src/main/java/com/bank/connect/demo/ConnectDemo.java ───
// Models the Connect runtime: a JDBC source + S3 sink driven by config, with
// source offsets and sink offsets so both resume after a restart. No bespoke
// producer/consumer business logic — the connectors do the moving.
package com.bank.connect.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ConnectDemo {

    private static final Logger log = Logger.getLogger("KafkaConnect");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountTable db = new AccountTable();
        db.insert(new AccountRow(1, "SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        db.insert(new AccountRow(2, "CUR3001", "Priya Sharma", new BigDecimal("250000")));

        KafkaTopic topic = new KafkaTopic("bank.accounts");
        S3Bucket bucket = new S3Bucket("nbi-account-archive");

        JdbcSourceConnector source = new JdbcSourceConnector(db, topic, "id");
        S3SinkConnector sink = new S3SinkConnector(topic, bucket, /*flushSize*/ 2);

        log.info("=== source imports new DB rows INTO Kafka (no code) ===");
        source.poll();   // imports id 1 and 2

        log.info("=== sink exports Kafka records OUT to S3 files (no code) ===");
        sink.consume();  // writes a file of 2 records

        log.info("=== add a new row, restart: both resume from saved offsets ===");
        db.insert(new AccountRow(3, "SAV2002", "Amit Verma", new BigDecimal("75000")));
        source.poll();   // imports only id 3 (resumes from offset 2)
        sink.consume();  // writes remaining record(s)

        log.info(() -> "topic size=" + topic.size() + " s3 files=" + bucket.fileCount());
    }
}

// ─── Would be in AccountRow.java ───
class AccountRow {
    final long id; final String accountNo; final String holder; final BigDecimal balance;
    AccountRow(long id, String accountNo, String holder, BigDecimal balance) {
            this.id = id;
            this.accountNo = accountNo
            this.holder = holder
            this.balance = balance;
    }
    String toJson() {
        return "{\"id\":" + id + ",\"accountNo\":\"" + accountNo + "\",\"holder\":\""
                + holder + "\",\"balance\":" + balance + "}";
    }
}

// ─── Would be in AccountTable.java (the external source system) ───
class AccountTable {
    private final List<AccountRow> rows = new ArrayList<>();
    void insert(AccountRow r) { rows.add(r); }
    List<AccountRow> rowsWithIdGreaterThan(long lastId) {
        List<AccountRow> out = new ArrayList<>();
        for (AccountRow r : rows) if (r.id > lastId) out.add(r);
        return out;
    }
}

// ─── Would be in KafkaTopic.java (the Kafka side) ───
class KafkaTopic {
    private final String name; private final List<String> records = new ArrayList<>();
    KafkaTopic(String name) { this.name = name; }
    void append(String record) { records.add(record); }
    List<String> from(int offset) { return new ArrayList<>(records.subList(offset, records.size())); }
    int size() { return records.size(); }
    String name() { return name; }
}

// ─── Would be in S3Bucket.java (the external sink system) ───
class S3Bucket {
    private static final Logger log = Logger.getLogger("KafkaConnect");
    private final String name; private int fileCount = 0;
    S3Bucket(String name) { this.name = name; }
    void writeFile(List<String> records) {
        fileCount++;
        log.info(() -> "wrote s3://" + name + "/accounts-" + fileCount + ".json with "
                + records.size() + " records");
    }
    int fileCount() { return fileCount; }
}

// ─── Would be in JdbcSourceConnector.java (config-driven, imports INTO Kafka) ───
class JdbcSourceConnector {
    private static final Logger log = Logger.getLogger("KafkaConnect");
    private final AccountTable db; private final KafkaTopic topic;
    private final String incrementingColumn;
    private long sourceOffsetLastId = 0;   // stored by Connect, survives restart
    JdbcSourceConnector(AccountTable db, KafkaTopic topic, String incrementingColumn) {
            this.db = db;
            this.topic = topic
            this.incrementingColumn = incrementingColumn;
    }
    void poll() {
        List<AccountRow> newRows = db.rowsWithIdGreaterThan(sourceOffsetLastId);
        for (AccountRow r : newRows) {
            topic.append(r.toJson());
            sourceOffsetLastId = r.id;      // advance source offset
            log.info(() -> "source imported " + incrementingColumn + "=" + r.id
                    + " -> topic " + topic.name());
        }
        if (newRows.isEmpty()) log.fine("source: no new rows");
    }
}

// ─── Would be in S3SinkConnector.java (config-driven, exports OUT of Kafka) ───
class S3SinkConnector {
    private static final Logger log = Logger.getLogger("KafkaConnect");
    private final KafkaTopic topic; private final S3Bucket bucket; private final int flushSize;
    private int sinkOffset = 0;            // Kafka consumer offset, committed after write
    S3SinkConnector(KafkaTopic topic, S3Bucket bucket, int flushSize) {
            this.topic = topic;
            this.bucket = bucket
            this.flushSize = flushSize;
    }
    void consume() {
        List<String> pending = topic.from(sinkOffset);
        if (pending.isEmpty()) { log.fine("sink: nothing to flush"); return; }
        bucket.writeFile(pending);          // write first, THEN commit offset
        sinkOffset += pending.size();
        log.info(() -> "sink committed offset=" + sinkOffset + " (file flushed first)");
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
